from lesson_authoring import entry as E
W=[
E('tomography','英 /təˈmɒɡrəfi/；美 /təˈmɑːɡrəfi/','断层成像','像一层层查看面包的截面，只不过得到的是内部切面的图像。','tomo- 切片、截面 + -graphy 记录、成像。',[['希腊 tomos 截面 + graph- 记录','对内部截面作记录'],['现代科学构词 tomography','断层成像']],'CT 里的 T 就是 tomography。机器从数据生成内部截面图，不是把身体真的切开；computed tomography 是计算机断层成像。记住“看一层一层的截面”就能理解名称。','computed tomography；tomography images；a tomography scan。','tomography 说的是断层成像这一类方法，CT 是其中一种。不能把所有 tomography 都理解为同一种射线或同一台机器。',('Computed tomography produces detailed images of internal structures.','计算机断层成像生成内部结构的详细图像。'),('The researchers used tomography to examine the inside of the fossil.','研究人员用断层成像检查化石内部。'),sources=['https://en.wiktionary.org/wiki/tomography','https://www.nibib.nih.gov/science-education/science-topics/computed-tomography-ct']),
E('entomologist','英 /ˌentəˈmɒlədʒɪst/；美 /ˌentəˈmɑːlədʒɪst/','昆虫学家','专门研究昆虫的人：它们怎么生活、繁殖，以及如何与环境互动。','entomology 昆虫学 + -ist；entomon 的命名联系昆虫身体分节、似被切分的样子。',[['希腊 entomon → entomology','有分节切痕的生物、昆虫 → 昆虫学'],['entomology + -ist → entomologist','昆虫学 → 昆虫学家']],'这个词的切分画面在昆虫身体的节段，不是在说研究者把昆虫切碎。entomologist 可以研究授粉、害虫或昆虫行为，远不止收集标本。','an entomologist；a medical entomologist；consult an entomologist。','etymologist 是词源学家，entomologist 是昆虫学家。我们现在做词源学习，学到的是 entomologist 这个词。',('An entomologist identified the insect found in the garden.','一位昆虫学家鉴定了花园里发现的昆虫。'),('The entomologist studies how bees find food.','这位昆虫学家研究蜜蜂如何寻找食物。')),
E('entomological','英 /ˌentəməˈlɒdʒɪkəl/；美 /ˌentəməˈlɑːdʒɪkəl/','昆虫学的；有关昆虫研究的','标本柜、研究论文或学会，主题都围着昆虫转。','entomology + -ical，构成表示研究领域的形容词。',[['希腊 entomon → 英语 entomology','分节的昆虫 → 昆虫学'],['entomology + -ical → entomological','昆虫学 → 昆虫学方面的']],'entomological collection 是昆虫标本收藏，entomological research 是昆虫研究。它说明所属领域，不能只翻成宽泛的“生物学的”。','entomological research；an entomological collection；an entomological society。','entomological 讲昆虫；etymological 讲词源。二者拼写相近，主题完全不同。',('The museum has a large entomological collection.','这家博物馆拥有大量昆虫标本。'),('She presented her findings at an entomological conference.','她在一次昆虫学会议上介绍了研究发现。'))]
